import { site } from "./site";

export type StockStatus = "in" | "low" | "request";

export type ProductArt =
  | "mcb"
  | "rcd"
  | "socket"
  | "switch"
  | "cable"
  | "panel"
  | "floodlight"
  | "batten"
  | "exit"
  | "solar"
  | "inverter"
  | "battery"
  | "controller"
  | "dboard"
  | "conduit"
  | "toolbox"
  | "meter"
  | "changer";

export type Product = {
  slug: string;
  name: string;
  brand: string;
  /** GHS. null = quote-only / on request */
  price: number | null;
  /** unit of sale, e.g. "piece", "90 m coil" */
  unit: string;
  stock: StockStatus;
  /** remaining units when stock is low */
  stockLeft?: number;
  sku: string;
  /** catalogue category (spec §05) */
  category: CategoryId;
  /** homepage merchandising collections */
  collections: CollectionId[];
  /** short headline spec shown on cards */
  keySpec: string;
  specs: { label: string; value: string }[];
  description: string;
  /** compatibility / safety notes */
  notes?: string;
  warranty: string;
  art: ProductArt;
  /** drop a real product photo in /public/products/<slug>.webp to override the illustration */
  image?: string;
};

export type CategoryId =
  | "breakers"
  | "cables"
  | "switches"
  | "conduits"
  | "lighting"
  | "solar"
  | "tools"
  | "accessories";

